mapper.select:
SELECT t.id, t.title, t.detail, c.name AS category, t.priority, t.due_date, t.completed, CASE WHEN t.completed = TRUE THEN 'COMPLETED' ELSE t.status END AS status, t.created_at, t.updated_at, COALESCE(a.attachment_count, 0) AS attachment_count, COALESCE(s.subtask_count, 0) AS subtask_count, COALESCE(s.completed_subtask_count, 0) AS completed_subtask_count FROM todos t JOIN todo_categories c ON c.id = t.category_id LEFT JOIN ( SELECT todo_id, COUNT(*) AS attachment_count FROM todo_attachments GROUP BY todo_id ) a ON a.todo_id = t.id LEFT JOIN ( SELECT todo_id, COUNT(*) AS subtask_count, SUM(CASE WHEN completed = TRUE THEN 1 ELSE 0 END) AS completed_subtask_count FROM todo_subtasks GROUP BY todo_id ) s ON s.todo_id = t.id
AND t.title LIKE CONCAT('%', #{keyword}, '%')
AND c.name = #{category}
AND t.due_date >= #{from}
AND t.due_date <= #{to}
ORDER BY t.due_date ${order}
